_language = "zh"

def configure(argv=None):
    global _language
    values = list(sys.argv[1:] if argv is None else argv)
    boundary = values.index("--") if "--" in values else len(values)
    _language = "zh"
    index = 0
    while index < boundary:
        if values[index] == "--lang":
            if index + 1 >= boundary or values[index + 1] not in {"zh", "en"}:
                raise SystemExit("--lang: choose zh or en")
            _language = values[index + 1]
            del values[index:index + 2]
            boundary -= 2
        elif values[index].startswith("--lang="):
            value = values[index].split("=", 1)[1]
            if value not in {"zh", "en"}:
                raise SystemExit("--lang: choose zh or en")
            _language = value
            del values[index]
            boundary -= 1
        else:
            index += 1
    return values

def t(text, language=None):
    text = str(text)
    if (language or _language) != "en":
        return text
    if text in D:
        return D[text]
    # 只用于帮助、错误和人读结论；不用于JSON正文或用户数据。
    import re
    terms = sorted((key for key in D if len(key) >= 2), key=len, reverse=True)
    return re.sub("|".join(re.escape(key) for key in terms), lambda match: D[match.group()], text)

class Parser(argparse.ArgumentParser):
    def _print_message(self, message, file=None):
        return super()._print_message(t(message) if message else message, file)

def write_summary(directory, report):
    directory = Path(directory)
    if not directory.is_dir():
        return
    metrics = {
        "status": "Status", "complete": "Complete", "records": "Exported records",
        "original_records": "Original records", "kept_records": "Retained records",
        "pages": "Saved pages", "completed_tasks": "Completed queries", "tasks": "Queries",
        "input_units": "Input units", "output_units": "Output units", "executions": "Executions",
        "runs": "Executions", "tests": "Tests", "seconds": "Elapsed seconds",
        "total_checked": "Source counts checked", "export_checked": "Export counts checked",
        "independent_verified": "Independent reproduction verified", "one_minimal": "Single-deletion checks passed",
        "passed": "Verified products", "failed": "Failed products", "total": "Total products",
    }
    lines = ["# Execution summary", "", "This file translates task metadata. Original files, field names and machine-readable results are retained.", ""]
    for key, label in metrics.items():
        if key in report:
            value = report[key]
            if key == "status":
                value = t(value, "en")
            lines.append(f"- {label}: {value}")
    if report.get("error"):
        lines += ["", "Error: " + t(report["error"], "en")]
    if report.get("source_time"):
        lines += ["", "Source data time: " + t(report["source_time"], "en")]
    (directory / "Summary.en.md").write_text("\n".join(lines) + "\n", encoding="utf-8")
